const cfg=window.APP_CONFIG||{}, $=s=>document.querySelector(s), state={session:null,user:null,family:null,swimmers:[],swimmer:null,grants:[],members:[],lists:[],swims:[],goals:[],meets:[],meetEvents:[],kidLinks:[],kidDevices:[],pairingReady:false,kidLinkError:false,messages:[],messageError:'',messageRaceId:null,messageDrafts:{},messageSending:false,meetAnnouncements:[],meetAnnouncementError:'',tab:'home'};
if(sessionStorage.getItem('fst_after_member_removal')){state.tab='family';sessionStorage.removeItem('fst_after_member_removal')}
