function safeColor(c,fallback){return /^#[0-9a-f]{6}$/i.test(c||'')?c:fallback}
function applyTheme(){let f=state.family;document.documentElement.style.setProperty('--primary',safeColor(f?.primary_color,'#075b78'));document.documentElement.style.setProperty('--accent',safeColor(state.swimmer?.accent_color||f?.accent_color,'#eb8b4b'));$('#familyName').textContent=f?.name||'Swim With Me';$('#subtitle').textContent=state.swimmer?.name||'Your swim story, together';let mark=$('#logoBox');mark.replaceChildren();if(f?.logo_url&&(/^(https:\/\/|data:image\/jpeg;base64,)/.test(f.logo_url))){let img=document.createElement('img');img.alt='Family logo';img.src=f.logo_url;img.onerror=()=>mark.textContent='≈';mark.append(img)}else mark.textContent='≈'}
async function photoData(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Choose a JPG, PNG, or WebP picture.');if(file.size>15*1024*1024)throw Error('Choose a picture smaller than 15 MB.');let bitmap=await createImageBitmap(file),scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();let result=canvas.toDataURL('image/jpeg',.78);if(result.length>350000)throw Error('Picture is too large after resizing. Choose a smaller image.');return result}
