$('#recoveryForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,password=form.elements.password.value,confirm=form.elements.confirm.value,message=$('#authMessage');if(password.length<6){message.textContent='Use at least 6 characters.';return}if(password!==confirm){message.textContent='The passwords do not match.';return}const submit=form.querySelector('button[type=submit]');submit.disabled=true;message.textContent='Saving new password…';try{await request('/auth/v1/user',{method:'PUT',body:{password},token:recoveryToken});history.replaceState({},document.title,location.pathname+location.search);form.reset();form.hidden=true;$('#authForm').hidden=false;$('#signup').hidden=false;$('#forgotPassword').hidden=false;showLoginScreen('signin');message.textContent='Password updated. Sign in with your new password.'}catch(err){message.textContent=err.message}finally{submit.disabled=false}};
