async function loadRoot(){let f=await q('families','select=*&order=created_at.asc');let invites=state.user.is_anonymous?[]:await q('family_invites','select=*&email=eq.'+encodeURIComponent(state.user.email));if(invites.length){for(let invite of invites){try{await insert('family_members',{family_id:invite.family_id,user_id:state.user.id});await remove('family_invites',invite.id)}catch(e){notify('Invitation: '+e.message)}}f=await q('families','select=*&order=created_at.asc')}state.family=f[0]||null;state.members=state.family?await q('family_members','select=*&family_id=eq.'+state.family.id):[];state.joinRequests=[];state.joinCode=null;state.joinError='';try{state.joinRequests=await q('family_join_requests','select=*&order=created_at.desc');if(owner()){const codes=await q('family_join_codes','select=*&family_id=eq.'+state.family.id);state.joinCode=codes[0]?.code||null}}catch{state.joinError='Run family_signup_migration.sql to enable family requests.'}try{state.kidLinks=await q('kid_profile_links','select=*');state.kidLinkError=false}catch{state.kidLinks=[];state.kidLinkError=true}try{state.kidDevices=await q('kid_devices','select=*&order=connected_at.desc');state.pairingReady=true}catch{state.kidDevices=[];state.pairingReady=false}state.swimmers=state.family?await q('swimmers','select=*&family_id=eq.'+state.family.id+'&order=created_at.asc'):[];state.grants=state.family?await q('access_grants','select=*'):[];state.lists=state.family?await q('family_lists','select=*&family_id=eq.'+state.family.id):[];if(state.family&&owner()){try{const directory=await request('/rest/v1/rpc/family_member_directory',{method:'POST',body:{p_family_id:state.family.id}});state.members=state.members.map(m=>({...m,...directory.find(d=>d.user_id===m.user_id)}))}catch{}}const kidLink=state.kidLinks.find(x=>x.user_id===state.user.id);if(kidLink){state.swimmers=state.swimmers.filter(x=>x.id===kidLink.swimmer_id);state.tab='kid'}else if(state.family&&!owner())state.tab='portal';let previous=state.swimmer?.id,linkedSwimmer=new URLSearchParams(location.search).get('swimmer');state.swimmer=state.swimmers.find(s=>s.id===linkedSwimmer)||state.swimmers.find(s=>s.id===previous)||state.swimmers[0]||null;let select=$('#swimmerSelect');select.replaceChildren();for(let s of state.swimmers){let opt=document.createElement('option');opt.value=s.id;opt.textContent=s.name;select.append(opt)}select.hidden=!state.swimmers.length;select.value=state.swimmer?.id||'';applyTheme();await loadSwimmer()}
