async function boot(){if(!await ensureSession()){showAuth();return}showApp();try{await loadRoot();if(!state.family&&!state.user?.is_anonymous){const freshUser=await request('/auth/v1/user');saveSession({...state.session,user:freshUser})}if(!state.family&&state.user?.user_metadata?.family_join_code&&!state.joinRequests?.length&&!state.joinError){try{await request('/rest/v1/rpc/request_family_access',{method:'POST',body:{p_code:state.user.user_metadata.family_join_code,p_name:state.user.user_metadata.full_name||'Family member'}});await loadRoot()}catch(err){notify('Family request: '+err.message)}}if(state.user?.is_anonymous&&!state.swimmer){showAuth();setLoginMode('swimmer');$('#authMessage').textContent='This device is not connected, or your parent disconnected it. Ask for a new pairing code.'}}catch(e){notify(e.message);render()}}
