function homeView(){let pbs=bests(),recent=state.swims.slice(0,4),upcoming=state.meets.filter(m=>m.date>=new Date().toISOString().slice(0,10)).sort((a,b)=>a.date.localeCompare(b.date));return `<div class="card hero"><div class="eyebrow">${esc(state.swimmer.team||'Swimmer profile')}</div><h1>${esc(state.swimmer.name)}</h1><p>Every practice and meet moves the story forward.</p>${editable()?'<button class="primary" data-action="newSwim">Add a result</button>':''}</div><div class="grid"><div class="card"><div class="eyebrow">Recorded swims</div><div class="metric">${state.swims.length}</div></div><div class="card"><div class="eyebrow">Personal bests</div><div class="metric">${pbs.length}</div></div><div class="card"><div class="eyebrow">Upcoming meets</div><div class="metric">${upcoming.length}</div></div></div><div class="grid"><div class="card"><div class="row between"><h2>Recent swims</h2><button data-tab="results">All results</button></div>${recent.map(s=>swimItem(s)).join('')||'<div class="empty">No results yet.</div>'}</div><div class="card"><h2>Goals</h2>${state.goals.slice(0,4).map(g=>goalItem(g)).join('')||'<div class="empty">Goals will appear here.</div>'}</div><div class="card"><h2>Next meet</h2>${upcoming.length?`<strong>${esc(upcoming[0].name)}</strong><p>${dateText(upcoming[0].date)} · ${esc(upcoming[0].place)}</p>`:'<div class="empty">No upcoming meets yet.</div>'}</div></div>`}
