 function coursesForEvent(){const values=[...new Set([...state.swims,...state.goals].filter(s=>s.event===eventSelect.value).map(s=>s.course).filter(Boolean))].sort();courseSelect.innerHTML=values.map(c=>`<option ${c===state.progressCourse?'selected':''}>${esc(c)}</option>`).join('')}
