 const goal=state.goals.find(g=>g.event===eventSelect.value&&g.course===courseSelect.value),standards=[['personal','Goal'],['b','B'],['bb','BB'],['a','A'],['aa','AA']].filter(([k])=>Number(goal?.[k])>0).map(([k,name])=>({key:k,name,value:Number(goal[k])}));
 const latest=all.at(-1),previous=all.at(-2),pb=all.length?all.reduce((a,b)=>Number(a.seconds)<=Number(b.seconds)?a:b):null,first=all[0],goalTime=Number(goal?.personal)||0,seasonFirst=(all.filter(s=>String(s.date||'').startsWith(nowYear))[0]||first),seasonData=all.filter(s=>String(s.date||'').startsWith(nowYear)),seasonPB=seasonData.length?Math.min(...seasonData.map(s=>Number(s.seconds))):Number(pb?.seconds||0),improve=seasonFirst?Number(seasonFirst.seconds)-seasonPB:0,lastDelta=latest&&previous?Number(latest.seconds)-Number(previous.seconds):null,toGoal=pb&&goalTime?Math.max(0,Number(pb.seconds)-goalTime):null,progressPct=pb&&goalTime&&first&&Number(first.seconds)>goalTime?Math.max(0,Math.min(100,(Number(first.seconds)-Number(pb.seconds))/(Number(first.seconds)-goalTime)*100)):pb&&goalTime&&Number(pb.seconds)<=goalTime?100:null;
