 const values=[...data.map(s=>Number(s.seconds)),...standards.map(g=>g.value)];if(!values.length){svg.setAttribute('viewBox','0 0 760 380');svg.innerHTML='<text x="40" y="180" fill="currentColor">No times or goals for this event yet.</text>';return}
